// @vitest-environment jsdom
//
// THE DOCBLOCK IS LOAD-BEARING. `vitest.config.ts` splits environments on the `lib/` boundary — a
// `lib/` test is pure logic and gets `node`, because building a jsdom per file cost 890s against 103s
// of actual tests. This one lives in `lib/` and DOES need a DOM: it renders a hook. The config names
// this docblock as the way out, and without it the whole suite fails on `document is not defined`.
// Carried test for `@/features/algorithms/lib/useImplSource`.
import { describe, it, expect, vi, beforeEach } from "vitest";
import { renderHook, waitFor } from "@testing-library/react";

const loadImplSource = vi.fn();
vi.mock("@/features/algorithms/lib/graphBridge", () => ({ loadImplSource: (id: string) => loadImplSource(id) }));

import { useImplSource } from "@/features/algorithms/lib/useImplSource";

describe("useImplSource", () => {
  beforeEach(() => {
    loadImplSource.mockReset();
    loadImplSource.mockResolvedValue({ code: "fetched body" });
  });

  it("does not fetch when the record already carries its own code", async () => {
    // The packaged seed carries bodies, so the common first paint must cost NOTHING.
    const { result } = renderHook(() => useImplSource("a.ts", "seeded body"));
    expect(result.current).toBe("seeded body");
    await new Promise((r) => setTimeout(r, 0));
    expect(loadImplSource).not.toHaveBeenCalled();
  });

  it("fetches the body for a record the index carries without one", async () => {
    const { result } = renderHook(() => useImplSource("a.ts", undefined));
    await waitFor(() => expect(result.current).toBe("fetched body"));
    expect(loadImplSource).toHaveBeenCalledWith("a.ts");
  });

  it("shows nothing rather than the PREVIOUS record's body while a fetch is in flight", async () => {
    // The bug this ordering exists to prevent: select B, and A's source sits under B's name until the
    // fetch lands. Wrong source attributed to the wrong record is worse than an empty pane.
    const { result, rerender } = renderHook(({ id }) => useImplSource(id, undefined), {
      initialProps: { id: "a.ts" },
    });
    await waitFor(() => expect(result.current).toBe("fetched body"));

    let release: (v: unknown) => void = () => {};
    loadImplSource.mockReturnValue(new Promise((r) => { release = r; }));
    rerender({ id: "b.ts" });
    expect(result.current, "the previous record's body must be gone immediately").toBeUndefined();
    release({ code: "b body" });
    await waitFor(() => expect(result.current).toBe("b body"));
  });

  it("renders nothing when the source cannot be read, rather than throwing", async () => {
    loadImplSource.mockResolvedValue(null);
    const { result } = renderHook(() => useImplSource("a.ts", undefined));
    await new Promise((r) => setTimeout(r, 0));
    expect(result.current).toBeUndefined();
  });

  it("re-fetches when the body's hash moves — a librarian's live edit must land", async () => {
    // The index carries NO bodies, so `codeHash` is the only thing that can tell this hook a body
    // changed. Without it in the deps the pane serves the first body it ever fetched, forever — and a
    // live edit is exactly what the page's 5-second poll exists for.
    const { result, rerender } = renderHook(({ h }) => useImplSource("a.ts", undefined, h), {
      initialProps: { h: "hash-1" },
    });
    await waitFor(() => expect(result.current).toBe("fetched body"));
    expect(loadImplSource).toHaveBeenCalledTimes(1);

    loadImplSource.mockResolvedValue({ code: "edited body" });
    rerender({ h: "hash-2" });
    await waitFor(() => expect(result.current).toBe("edited body"));
  });

  it("does not re-fetch while the hash is unchanged", async () => {
    const { rerender } = renderHook(({ h }) => useImplSource("a.ts", undefined, h), {
      initialProps: { h: "hash-1" },
    });
    await waitFor(() => expect(loadImplSource).toHaveBeenCalledTimes(1));
    rerender({ h: "hash-1" });
    rerender({ h: "hash-1" });
    expect(loadImplSource).toHaveBeenCalledTimes(1);
  });
});

