// useImplSource (#the-algorithms-page-hydrates-fifty-megabytes-every-five-seconds) — the selected
// record's source, fetched on demand.
//
// WHY THIS EXISTS. `graph_dump` used to hand the page every record's `code`: 19.31 MB of a 20.26 MB
// hydrate, MEASURED over 1,401 records, to render the ONE body the inspector shows. When that transfer
// failed, `loadGraph` returned null and the page silently kept the packaged seed — a graph showing 757
// records instead of 1,401, with nothing to say so. The index no longer carries bodies; this asks for
// the one that is on screen.
//
// THE RECORD'S OWN `code` WINS when it has one, and that is not a fallback so much as the common case
// on first paint: the packaged seed DOES carry bodies, so a freshly mounted inspector has source to
// show before any fetch resolves, and the fetch only matters for records the live store has and the
// seed does not.
import { useEffect, useState } from "react";
import { loadImplSource } from "@/features/algorithms/lib/graphBridge";

/** The source to render for `id`.
 *
 *  `seeded` is the record's own `code` when it carries one (the packaged seed does). `codeHash` is the
 *  index's hash of the source — it is in the deps so a LIVE EDIT re-fetches: the index carries no
 *  bodies, so without it a librarian's `bsc graph impl set` would move nothing this hook can see and
 *  the pane would serve the first body it ever fetched, forever. */
export function useImplSource(
  id: string | undefined,
  seeded: string | undefined,
  codeHash?: string,
): string | undefined {
  const [fetched, setFetched] = useState<string | undefined>(undefined);
  useEffect(() => {
    // Clear FIRST, so selecting a record never shows the previous one's body while this resolves.
    setFetched(undefined);
    if (!id || seeded) return;
    let cancelled = false;
    void loadImplSource(id).then((src) => {
      if (!cancelled) setFetched(src?.code ?? undefined);
    });
    return () => {
      cancelled = true;
    };
  }, [id, seeded, codeHash]);
  return seeded ?? fetched;
}
